package com.harborledger.billing;

import java.time.ZoneId;

final class BillingTestFixture {
    private BillingTestFixture() {
    }

    static ZoneId newYorkBillingZone() {
        return ZoneId.of("America/New_York");
    }
}

package com.harborledger.billing;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.time.Instant;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

class InvoiceDueDateCalculatorTest {
    private final InvoiceDueDateCalculator calculator = new InvoiceDueDateCalculator();

    @Test
    void standardTermsUseAccountBillingZone() {
        Instant dueAt = calculator.dueAt(
                LocalDate.of(2026, 2, 2),
                30,
                BillingTestFixture.newYorkBillingZone());

        assertEquals(Instant.parse("2026-03-04T05:00:00Z"), dueAt);
    }

    @Test
    void rejectsNegativePaymentTerms() {
        assertThrows(
                IllegalArgumentException.class,
                () -> calculator.dueAt(
                        LocalDate.of(2026, 2, 2),
                        -1,
                        BillingTestFixture.newYorkBillingZone()));
    }
}

package com.harborledger.billing;

import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.Objects;

public final class InvoiceDueDateCalculator {
    public Instant dueAt(LocalDate issueDate, int termDays, ZoneId billingZone) {
        Objects.requireNonNull(issueDate, "issueDate");
        Objects.requireNonNull(billingZone, "billingZone");
        if (termDays < 0) {
            throw new IllegalArgumentException("termDays must be non-negative");
        }

        Instant issuedAt = issueDate.atStartOfDay(billingZone).toInstant();
        return issuedAt.plus(Duration.ofDays(termDays));
    }
}

